mapper.sql:
c.tenant_id = #{tenantId} AND c.deleted = 0



    AND (c.owner_staff_id = #{selfId}

      OR c.team_id IN #{teamId}
    )

  AND c.owner_staff_id = #{selfId}
  AND 1 = 0

mapper.select:
SELECT (SELECT COALESCE(SUM(p.amount_fen), 0) FROM crm_payment_txn p INNER JOIN crm_order o ON o.tenant_id = p.tenant_id AND o.id = p.order_id WHERE p.tenant_id = #{tenantId} AND o.customer_id = #{customerId} AND p.status = 'CONFIRMED' AND p.confirmed_at >= #{startInclusive} AND p.confirmed_at < #{endExclusive}) AS paymentAmountFen, (SELECT COALESCE(SUM(o.paid_fen), 0) FROM crm_order o WHERE o.tenant_id = #{tenantId} AND o.customer_id = #{customerId} AND o.status NOT IN ('DRAFT', 'CANCELED') AND o.paid_at >= #{startInclusive} AND o.paid_at < #{endExclusive}) AS paidAmountFen, (SELECT COALESCE(SUM(rp.amount_fen), 0) FROM crm_refund_payment rp INNER JOIN crm_refund r ON r.tenant_id = rp.tenant_id AND r.id = rp.refund_id WHERE rp.tenant_id = #{tenantId} AND r.customer_id = #{customerId} AND rp.status = 'SUCCEEDED' AND rp.succeeded_at >= #{startInclusive} AND rp.succeeded_at < #{endExclusive}) AS refundAmountFen, (SELECT COUNT(*) FROM crm_order o WHERE o.tenant_id = #{tenantId} AND o.customer_id = #{customerId} AND o.status NOT IN ('DRAFT', 'CANCELED') AND o.ordered_at >= #{startInclusive} AND o.ordered_at < #{endExclusive}) AS orderCount, (SELECT COUNT(*) FROM crm_followup f WHERE f.tenant_id = #{tenantId} AND f.customer_id = #{customerId} AND f.deleted = 0 AND f.contact_at >= #{startInclusive} AND f.contact_at < #{endExclusive}) AS manualFollowupCount, (SELECT COUNT(*) FROM crm_wecom_message m WHERE m.tenant_id = #{tenantId} AND m.customer_id = #{customerId} AND m.status = 'STORED' AND m.consent_snapshot = 'GRANTED' AND m.sent_at >= #{startInclusive} AND m.sent_at < #{endExclusive}) AS archivedMessageCount, CASE WHEN EXISTS (
SELECT 1 FROM crm_wecom_contact wc LEFT JOIN crm_wecom_cursor cursor_row ON cursor_row.tenant_id = wc.tenant_id AND cursor_row.corp_id = wc.corp_id AND cursor_row.archive_scope = #{archiveScope} WHERE wc.tenant_id = #{tenantId} AND wc.customer_id = #{customerId} AND (cursor_row.id IS NULL OR cursor_row.data_gap = 1 OR EXISTS ( SELECT 1 FROM crm_wecom_data_gap gap WHERE gap.tenant_id = wc.tenant_id AND gap.corp_id = wc.corp_id AND gap.archive_scope = #{archiveScope} AND gap.status = 'OPEN'))
SELECT 1 FROM crm_wecom_contact wc WHERE wc.tenant_id = #{tenantId} AND wc.customer_id = #{customerId}
) THEN 0 ELSE 1 END AS communicationComplete

SELECT  FROM crm_customer_tier_metric_snapshot
WHERE tenant_id = #{tenantId} AND recalculation_key = #{recalculationKey}
FOR UPDATE
